   290	{
   291	        int status = 0;
   292	
   293	        if (event == EVENT_NCP_RESET) {
   294	                if (mDriverState == INITIALIZING) {
   295	                        syslog(LOG_ERR, "Unexpected reset during NCP initialization.");
   296	                        mFailureCount++;
   297	                        PT_INIT(&mSubPT);
   298	                } else if (mDriverState == INITIALIZING_WAITING_FOR_RESET) {
   299	                        mDriverState = INITIALIZING;
   300	                }
   301	        }
