   303	        EH_BEGIN_SUB(&mSubPT);
   304	
   305	        if (get_ncp_state() == UPGRADING) {
   306	                EH_WAIT_UNTIL(get_upgrade_status() != EINPROGRESS);
   307	
   308	                status = get_upgrade_status();
   309	
   310	                if (status == 0) {
   311	                        syslog(LOG_INFO, "Firmware Update Complete.");
   312	                } else {
   313	                        syslog(LOG_ERR, "Firmware Update Failed with Error %d", status);
   314	                        mFailureCount++;
   315	
   316	                        if (mFailureCount > mFailureThreshold) {
   317	                                change_ncp_state(FAULT);
   318	                        }
   319	                }
   320	        }
   321	
   322	        if (get_ncp_state() == FAULT) {
   323	                EH_EXIT();
   324	        }
   325	
   326	        syslog(LOG_INFO, "Initializing NCP");
   327	
   328	        set_initializing_ncp(true);
   329	
   330	        change_ncp_state(UNINITIALIZED);
   331	
