   335	
   336	        mNCPVersionString = "";
   337	
   338	        mDriverState = INITIALIZING_WAITING_FOR_RESET;
   339	
   340	        if (mResetIsExpected) {
   341	                EH_WAIT_UNTIL_WITH_TIMEOUT(NCP_DEFAULT_COMMAND_RESPONSE_TIMEOUT, mResetIsExpected == false);
   342	
   343	                if (eh_did_timeout) {
   344	                        // mResetIsExpected has been set for too long and we
   345	                        // haven't gotten a reset yet. This can prevent us from sleeping.
   346	                        // by incrementing the failure count here we will cause
   347	                        // another reset to occur in the code below.
   348	                        mFailureCount++;
   349	                        mResetIsExpected = false;
   350	                        syslog(LOG_ERR, "Was waiting for a reset, but we never got one.");
   351	                }
   352	        } else {
   353	                // Backoff delay. Normaly zero. May increase if we are in a reset loop.
   354	                EH_SLEEP_FOR(mRunawayResetBackoffManager.delay_for_unexpected_reset());
   355	        }
   356	
   357	        do {
   358	                EH_SLEEP_FOR(0.1);
   359	
   360	                if (mFailureCount > mFailureThreshold) {
   361	                        syslog(LOG_ALERT, "The NCP is misbehaving: Repeatedly unable to initialize NCP. Entering fault state.");
   362	                        change_ncp_state(FAULT);
   363	                        EH_EXIT();
   364	                }
   365	
   366	                if ( mAutoUpdateFirmware
   367	                  && (mFailureCount > (mFailureThreshold - 1))
   368	                  && can_upgrade_firmware()
   369	                ) {
   370	                        syslog(LOG_ALERT, "The NCP is misbehaving: Attempting a firmware update");
   371	                        upgrade_firmware();
   372	                        EH_RESTART();
   373	                }
   374	
   375	                if ((event != EVENT_NCP_RESET) && (mFailureCount > 0)) {
   376	                        syslog(LOG_ERR, "Resetting and trying again... (retry %d)", mFailureCount);
   377	
   378	                        change_ncp_state(UNINITIALIZED);
   379	
   380	                        mNetworkKey = Data();
   381	                        mNetworkKeyIndex = 0;
   382	
   383	                        reset_tasks(kWPANTUNDStatus_Canceled);
   384	
